"use client";

import type { ReactNode } from "react";

import { Button } from "@/components/ui/button";
import { EmojiPickerContent } from "@/registry/new-york/emoji-picker/EmojiPickerContent";
import { PickerPopover } from "@/registry/new-york/picker-popover/PickerPopover";

export interface EmojiPickerProps {
  value?: string;
  onChange: (emoji: string) => void;
  trigger?: ReactNode;
  disabled?: boolean;
  label?: string;
  theme?: "light" | "dark" | "auto";
}
export const EmojiPicker = ({
  value,
  onChange,
  trigger,
  disabled,
  label = "Choose emoji",
  theme,
}: EmojiPickerProps) => (
  <PickerPopover
    label={label}
    disabled={disabled}
    trigger={
      trigger ?? (
        <Button
          variant="outline"
          disabled={disabled}
          aria-label={label}
          className="size-10 cursor-pointer p-0 text-xl shadow-none"
        >
          {value || "😀"}
        </Button>
      )
    }
  >
    {(close) => (
      <EmojiPickerContent
        theme={theme}
        onSelect={(emoji) => {
          onChange(emoji);
          close();
        }}
      />
    )}
  </PickerPopover>
);

"use client";

import { lazy, Suspense } from "react";
import { ErrorBoundary } from "react-error-boundary";

const EmojiLibrary = lazy(() => import("./EmojiLibrary"));

export interface EmojiPickerContentProps {
  onSelect: (emoji: string) => void;
  theme?: "light" | "dark" | "auto" | undefined;
}
export const EmojiPickerContent = ({
  onSelect,
  theme = "auto",
}: EmojiPickerContentProps) => (
  <ErrorBoundary
    fallback={
      <p role="alert" className="block h-[440px] p-4 text-sm">
        Emoji picker could not load. Reload the page to retry.
      </p>
    }
  >
    <Suspense
      fallback={
        <output className="block h-[440px] p-4 text-sm">Loading emoji…</output>
      }
    >
      <EmojiLibrary theme={theme} onSelect={onSelect} />
    </Suspense>
  </ErrorBoundary>
);

"use client";

import Picker, { EmojiStyle, Theme } from "emoji-picker-react";

const metrics = {
  "--epr-header-padding": "12px",
  "--epr-horizontal-padding": "12px",
  "--epr-search-input-height": "36px",
  border: 0,
  borderRadius: 0,
};
const appColors = {
  "--epr-bg-color": "var(--picker-surface, var(--color-popover))",
  "--epr-category-icon-active-color": "var(--color-foreground)",
  "--epr-category-label-bg-color":
    "var(--picker-surface, var(--color-popover))",
  "--epr-category-label-text-color": "var(--color-muted-foreground)",
  "--epr-focus-bg-color": "var(--color-muted)",
  "--epr-highlight-color": "var(--color-ring)",
  "--epr-hover-bg-color": "var(--color-muted)",
  "--epr-search-border-color": "transparent",
  "--epr-search-input-bg-color":
    "color-mix(in srgb, var(--color-muted) 60%, transparent)",
  "--epr-search-input-bg-color-active":
    "color-mix(in srgb, var(--color-muted) 60%, transparent)",
  "--epr-text-color": "var(--color-muted-foreground)",
};
const themes = { auto: Theme.AUTO, dark: Theme.DARK, light: Theme.LIGHT };
const EmojiLibrary = ({
  theme,
  onSelect,
}: {
  theme: "auto" | "light" | "dark";
  onSelect: (emoji: string) => void;
}) => (
  <Picker
    width="100%"
    height={440}
    style={theme === "auto" ? { ...metrics, ...appColors } : metrics}
    theme={themes[theme]}
    emojiStyle={EmojiStyle.NATIVE}
    lazyLoadEmojis
    previewConfig={{ showPreview: false }}
    onEmojiClick={(emoji) => onSelect(emoji.emoji)}
  />
);
export default EmojiLibrary;

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
